import sys

def get_down_connections(col, start_r, lines):
    # trace down from start_r at col
    r = start_r
    # find the box
    box_bottom = -1
    while r < len(lines):
        if col < len(lines[r]) and lines[r][col] in '+-~':
            # hit box top, now find box bottom
            br = r + 1
            while br < len(lines) and (col >= len(lines[br]) or lines[br][col] not in '+-~'):
                br += 1
            if br < len(lines):
                box_bottom = br
                break
        r += 1

    if box_bottom == -1: return 0

    # check if there is a line going down from box bottom
    r = box_bottom + 1
    if r >= len(lines) or col >= len(lines[r]) or lines[r][col] not in '|\\/+':
        return 0

    # follow the | down to a horizontal line
    while r < len(lines):
        if col < len(lines[r]) and lines[r][col] in '-~_+':
            break
        r += 1

    if r >= len(lines):
        # maybe it directly connects to a box?
        r = box_bottom + 1
        while r < len(lines):
            if col < len(lines[r]) and lines[r][col] in '+-~':
                return 1
            if col >= len(lines[r]) or lines[r][col] == ' ':
                return 0
            r += 1
        return 0

    # find segment boundaries on this horizontal line
    line = lines[r]

    segs = []
    in_seg = False
    start = 0
    for i, c in enumerate(line):
        if c != ' ':
            if not in_seg:
                start = i
                in_seg = True
        else:
            if in_seg:
                segs.append((start, i-1))
                in_seg = False
    if in_seg:
        segs.append((start, len(line)-1))

    # find the block of segments connected by gap=1 that includes `col`
    block_start = -1
    block_end = -1
    for i in range(len(segs)):
        if segs[i][0] <= col <= segs[i][1] or (i > 0 and segs[i-1][1] < col < segs[i][0] and segs[i][0] - segs[i-1][1] - 1 <= 2):
            left_idx = i
            while left_idx > 0 and segs[left_idx][0] - segs[left_idx-1][1] - 1 <= 2:
                left_idx -= 1
            right_idx = i
            while right_idx < len(segs) - 1 and segs[right_idx+1][0] - segs[right_idx][1] - 1 <= 2:
                right_idx += 1
            block_start = segs[left_idx][0]
            block_end = segs[right_idx][1]
            break

    if block_start == -1:
        return 0

    next_line = lines[r+1] if r+1 < len(lines) else ""
    down_cols = []
    for c in range(block_start, block_end + 1):
        if c < len(next_line) and next_line[c] in '|\\/+_':
            down_cols.append(c)

    return len(down_cols)

def main():
    lines = open('/app/dataset/genealogy_trees.txt').read().splitlines()

    children = [3014, 3018, 3043, 3081]
    total_grandchildren = 0
    for c in children:
        gc = get_down_connections(c, 62, lines)
        print(f"Child at {c} has {gc} children")
        total_grandchildren += gc

    print(f"Total grandchildren for Julita Kucharz: {total_grandchildren}")

if __name__ == "__main__":
    main()

